import json

h, w = 20, 20
out = [[0]*w for _ in range(h)]

# Rectangle bounds
rect_c_start, rect_c_end = 9, 15

# Markers in top region (that affect rows 0-8)
marker_rows = {2, 3, 4, 7, 8}  # rows with markers

# Sieve cols (absolute, from demo analysis)
sieve_cols = [2, 4, 6, 7]

# Bottom markers for column injection
bottom_markers = [(12, 9), (17, 13), (19, 15)]

def is_full_row(r):
    """Row is full if distance 1 from a marker row but not a marker row itself"""
    if r in marker_rows:
        return False
    for mr in marker_rows:
        if abs(r - mr) == 1:
            return True
    return False

# Top region: rows 0-8
for r in range(9):
    if r in marker_rows:
        # Marker row: expanded to 20 cols (8-19)
        for c in range(8, 20):
            out[r][c] = 2
    elif is_full_row(r):
        # Full row (adjacent to marker)
        for c in range(w):
            out[r][c] = 2
    else:
        # Basic: rect cols only
        for c in range(rect_c_start, rect_c_end + 1):
            out[r][c] = 2

# Bottom region: sieve pattern at absolute cols [2,4,6,7]
for r in range(9, h):
    for c in sieve_cols:
        out[r][c] = 2

# Marker injections in bottom region
for r, c in bottom_markers:
    out[r][c] = 2

# Submit
print(json.dumps({"action": "submit", "grid": out}))
